(function(){'use strict';if(location.protocol==='file:')return;
const cloud={state:null,pending:null,busy:false,syncing:false,lastSync:null,status:'loading',remoteChanged:false};window.THCloud=cloud;
function unavailable(message){cloud.state=null;cloud.status='locked';db=null;closeModal();app.innerHTML='<div class="access-pending"><div class="brand-name">top hills✳</div><h1>Akses perlu diperiksa.</h1><p>'+esc(message)+'</p><button class="btn" data-cloud-retry>Coba lagi</button><p><a class="btn primary" href="/login" target="_top">Masuk ke Top Hills</a></p></div>';}
cloud.api=async function(path,data,method='POST'){const headers={'X-Top-Hills':'1'},opts={method,headers,credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(25000)};if(data instanceof FormData){const limit=globalThis.THHosting?.maxUploadBytes;for(const value of data.values())if(limit&&typeof value?.size==='number'&&value.size>limit)throw Error('File terlalu besar. Pilih file maksimal '+(limit/1000000)+' MB.');opts.body=data;}else if(data!==undefined){headers['Content-Type']='application/json';opts.body=JSON.stringify(data);}let res;try{res=await fetch('/api/'+path,opts)}catch(e){cloud.status='offline';cloud.paintStatus();throw Error('Koneksi terputus atau terlalu lambat. Perubahan belum dikonfirmasi tersimpan; input tetap tersedia.');}let out;try{out=await res.json()}catch{throw Error('Data belum dapat dibaca. Isian Anda tetap tersedia.')}if(!res.ok){const err=Object.assign(Error(THCopy.error(out.error||'Penyimpanan belum berhasil.')),{httpStatus:res.status});if(res.status===401||res.status===403&&['state','sync'].includes(path))unavailable(err.message);throw err;}return out;};
cloud.apply=function(value){const first=!cloud.state;if(value.maintenance?.resetId){try{if(localStorage.getItem('th-applied-reset')!==value.maintenance.resetId){localStorage.removeItem('top-hills-journal-v1');localStorage.removeItem('th-finance-filters');if(window.THFinance)THFinance.state.saved=[];localStorage.setItem('th-applied-reset',value.maintenance.resetId);}}catch{}}if(value.laundry===undefined&&value.member.id===cloud.state?.member.id&&value.member.role===cloud.state?.member.role)value.laundry=cloud.state.laundry;cloud.state=value;db=JSON.parse(JSON.stringify(value.operations));ui.role=value.member.role;ui.employee=value.member.profile.employeeId||(value.member.role==='Owner'?db.employees.find(e=>e.active)?.id:'')||'';ui.consumer=value.member.profile.customerId||'';if(first)ui.date=value.clock;cloud.lastSync=Date.now();cloud.status='synced';cloud.remoteChanged=false;storageOK=true;};
cloud.load=async function(){cloud.apply(await cloud.api('state',undefined,'GET'));render();};
cloud.mutate=async function(path,value={}){if(cloud.busy)throw Error('Masih menyimpan. Tunggu sebentar.');if(!cloud.state)throw Error('Masuk kembali untuk menyimpan.');if(!navigator.onLine)throw Error('Perangkat sedang offline. Sambungkan internet sebelum menyimpan.');cloud.busy=true;cloud.status='saving';cloud.paintStatus();try{const key=JSON.stringify({path,value});if(!cloud.attempt||cloud.attempt.key!==key)cloud.attempt={key,payload:{...value,revision:cloud.state.revision,mutationId:crypto.randomUUID()}};try{const result=await cloud.api(path,cloud.attempt.payload);cloud.attempt=null;cloud.apply(result);return result;}catch(e){if(e.httpStatus&&e.httpStatus<500)cloud.attempt=null;if(e.httpStatus===409){cloud.apply(await cloud.api('state',undefined,'GET'));e.message='Ada perubahan dari perangkat lain. Input Anda tetap ada. Salin bila perlu, lalu tutup dan buka formulir kembali untuk meninjau data terbaru.';}throw e;}}finally{cloud.busy=false;if(cloud.status==='saving')cloud.status='error';cloud.paintStatus();}};
cloud.saveOps=function(message){const outgoing=JSON.parse(JSON.stringify(db));cloud.pending=cloud.mutate('operations',{operations:outgoing}).then(()=>{render();if(message)toast(message);}).catch(e=>{if(cloud.state){db=JSON.parse(JSON.stringify(cloud.state.operations));render();}throw e;});return cloud.pending;};
cloud.start=async function(){app.innerHTML='<div class="access-pending"><div class="brand-name">top hills✳</div><h1>Membuka ruang kerja.</h1><p>Mengambil data terbaru…</p></div>';try{await cloud.load();const params=new URLSearchParams(location.search);ui.page=params.get('view')==='finance'?'finance':'home';if(ui.page==='finance'&&params.get('order')){const id=params.get('order'),order=cloud.state.laundry?.orders.find(o=>o.id===id),dates=cloud.state.finance?.transactions.filter(t=>t.orderId===id).map(t=>t.date)||[];if(order)dates.push(order.created.slice(0,10));THFinance.state.filter.customer='portal:'+id;if(dates.length){THFinance.state.filter.start=dates.sort()[0];THFinance.state.filter.end=dates.at(-1)>cloud.state.clock?dates.at(-1):cloud.state.clock;THFinance.state.preset='custom';}}render();}catch(e){if(cloud.status!=='locked')unavailable(e.message);}};
cloud.paintStatus=function(){const el=document.querySelector('[data-sync-status]');if(!el)return;const label=cloud.remoteChanged?'Pembaruan tersedia':({synced:'Tersinkron',saving:'Menyimpan…',offline:'Offline · belum tersinkron',error:'Periksa penyimpanan',loading:'Menghubungkan…',locked:'Akses dibatasi'})[cloud.status];el.textContent=label||'Periksa koneksi';el.dataset.state=cloud.status;el.title=cloud.lastSync?'Sinkron terakhir '+new Date(cloud.lastSync).toLocaleTimeString('id-ID',{timeZone:'Asia/Jakarta'})+' WIB':'';};
cloud.refresh=async function(){if(!cloud.state||cloud.busy||cloud.syncing||document.visibilityState==='hidden')return;cloud.syncing=true;try{const v=await cloud.api('sync',undefined,'GET');if(!cloud.state)return;const membership=JSON.stringify(v.member)!==JSON.stringify({id:cloud.state.member.id,role:cloud.state.member.role,status:cloud.state.member.status,profile:cloud.state.member.profile});if(membership){closeModal();await cloud.load();return;}if(v.revision!==cloud.state.revision||v.laundryRevision!==cloud.state.laundry?.revision){if(dialog.open||document.activeElement?.matches('input,textarea,select'))cloud.remoteChanged=true;else await cloud.load();}cloud.status='synced';cloud.lastSync=Date.now();}catch(e){if(cloud.status!=='locked')cloud.status='offline';}finally{cloud.syncing=false;cloud.paintStatus();}};
setInterval(()=>cloud.refresh(),15000);window.addEventListener('focus',()=>cloud.refresh());window.addEventListener('online',()=>cloud.refresh());document.addEventListener('visibilitychange',()=>cloud.refresh());window.addEventListener('offline',()=>{cloud.status='offline';cloud.paintStatus();});
window.THAccess={current:()=>cloud.state?.member,bind:()=>{if(!cloud.state)return false;ui.role=cloud.state.member.role;return true},cleanup(){},render(){},pending:()=>0,widget:()=>`<button class="sync-state" data-sync-status data-cloud-refresh aria-label="Periksa sinkronisasi">${cloud.remoteChanged?'Pembaruan tersedia':'Tersinkron'}</button><button class="portal-identity" data-cloud-profile><span class="avatar small blue">${initials(cloud.state?.member.name||'TH')}</span><span>${esc(cloud.state?.member.name||'')}<small>${esc(cloud.state?.member.role||'')}</small></span></button>`,manage:members};
async function members(){if(cloud.state.member.role!=='Owner')throw Error('Kelola akses memerlukan Owner.');const list=await cloud.api('members',undefined,'GET');openModal('Akses ruang kerja',`<p class="muted">Akses data mengikuti akun yang masuk. Pengguna baru tampil setelah mendapat akses situs dan masuk; Owner kemudian menetapkan tugasnya.</p>${list.map(m=>`<form data-cloud-member="${esc(m.id)}" class="fin-member"><strong>${esc(m.name)}</strong><small>${esc(m.email)}</small><small>Mengajukan: ${esc(JSON.parse(m.profile||'{}').requestedRole||m.role)}</small>${select('Peran','role',['Owner','Finance','Operator','Konsumen'],m.role)}${select('Status','status',['Aktif','Nonaktif','Menunggu'],m.status)}${select('Karyawan terkait','employeeId',[['','Tidak ditautkan'],...db.employees.map(e=>[e.id,e.name])],JSON.parse(m.profile||'{}').employeeId)}${select('Penghuni terkait','customerId',[['','Tidak ditautkan'],...db.tenants.map(t=>[t.id,t.name])],JSON.parse(m.profile||'{}').customerId)}<div class="form-error" role="alert"></div><button class="btn" type="submit">Simpan akses</button></form>`).join('')}`,true);}

document.addEventListener('click',async e=>{try{if(e.target.closest('[data-cloud-retry]'))await cloud.start();if(e.target.closest('[data-cloud-refresh]')){if(dialog.open){toast('Selesaikan atau tutup formulir dahulu. Input Anda tidak akan ditimpa.');return;}await cloud.load();toast('Data terbaru sudah dimuat.');}if(e.target.closest('[data-cloud-profile]'))openModal('Akun ruang kerja',`<h3>${esc(cloud.state.member.name)}</h3><p>${esc(cloud.state.member.email)}</p>${badge(cloud.state.member.role,'blue')}<p>Masuk dengan metode dan akun yang sama di setiap perangkat Anda. Untuk tim, setiap orang memakai akun sendiri dan diberi akses oleh Owner.</p><p class="muted">Data usaha diambil dari ruang kerja bersama. Koneksi internet diperlukan saat menyimpan. Keluar pada perangkat bersama. Login email memiliki pengaturan sesi perangkat tersendiri.</p><button class="btn" data-th-sessions>Sesi login email</button><button class="btn" data-th-logout>Keluar di perangkat ini</button>`);if(e.target.closest('[data-access="manage"]'))await members();}catch(err){toast(err.message);}});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-cloud-member]');if(!form)return;e.preventDefault();try{const d=Object.fromEntries(new FormData(form));await cloud.mutate('member',{...d,id:form.dataset.cloudMember});closeModal();render();toast('Akses diperbarui.');}catch(err){form.querySelector('.form-error').textContent=THCopy.error(err.message);}});
for(const key of Object.keys(actions)){const original=actions[key];actions[key]=async function(...args){cloud.pending=null;const result=await original(...args);if(cloud.pending)await cloud.pending;return result;};}
actions['new-order']=()=>{location.assign('/laundry-desk');};
actions.reset=actions.restore=()=>{throw Error('Riwayat bersama dilindungi. Koreksi data melalui menu Laporan.');};
actions.backup=()=>{if(!['Owner','Finance'].includes(cloud.state.member.role))throw Error('Cadangan lengkap memerlukan Owner atau Finance.');download('Top-Hills-Cadangan-'+THFinanceCore.today()+'.json',JSON.stringify({format:'top-hills-finance-v1',...cloud.state},null,2),'application/json');toast('Cadangan jurnal dan rincian bukti diunduh. File bukti tetap tersedia melalui rincian transaksi.');};
})();
